public void initFromQuotationLine(SalesQuotationLine _salesQuotationLine)
{
    this.ImportID   = _salesQuotationLine.salesQuotationTable().KCS_GAEBImportID;
    this.ArtQty     = _salesQuotationLine.SalesQty;
    this.ME         = _salesQuotationLine.SalesUnit;
    this.ShortTxt   = _salesQuotationLine.NDXProductName1;
    this.LongTxt    = _salesQuotationLine.Name;
}

/// <summary>
/// designed by AVANADE
/// </summary>
    /// <param name = "_importID">KCS_GAEBImportID</param>
    /// <param name = "_lfdNr">KCS_GAEBLfdNr</param>
    /// <returns>boolean</returns>
    static boolean exist(KCS_GAEBImportID _importID, KCS_GAEBLfdNr _lfdNr)
    {
        return _importID &&
           _lfdNr &&
           (select firstonly RecId from KCS_GAEBPos
                where KCS_GAEBPos.ImportID == _importID &&
                      KCS_GAEBPos.LfdNr == _lfdNr).RecId != 0;
    }

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_importID">KCS_GAEBImportID</param>
/// <param name = "_oz">KCS_GAEBOZ</param>
/// <returns>boolean</returns>
static boolean existOZ(KCS_GAEBImportID _importID, KCS_GAEBOZ _oz)
{
    return _importID &&
       _oz &&
       (select firstonly RecId from KCS_GAEBPos
            where KCS_GAEBPos.ImportID == _importID &&
                  KCS_GAEBPos.OZ == _oz).RecId != 0;
}

/// <summary>
    /// designed by AVANADE
/// </summary>
    /// <param name = "_importID">KCS_GAEBImportID</param>
    /// <param name = "_oz">KCS_GAEBOZ</param>
    /// <param name = "update">boolean</param>
    /// <returns>KCS_GAEBPos</returns>
    static KCS_GAEBPos find(KCS_GAEBImportID _importID,
                           KCS_GAEBOZ _oz,
                           boolean update = false)
    {
        KCS_GAEBPos bPos;
        if (_importID && _oz)
        {
            bPos.selectForUpdate(update);

            select firstonly bPos
            where bPos.ImportID == _importID &&
                  bPos.OZ == _oz;
        }
        return bPos;
    }

/// <summary>
/// designed by AVANADE
/// </summary>
    /// <param name = "ctrl">FormStringControl</param>
    /// <param name = "common">Common</param>
    client static void lookupImportId (FormStringControl ctrl, Common common)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tablenum(KCS_GAEBPos), ctrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tablenum(KCS_GAEBPos));
        QueryBuildRange         queryBuildRange = queryBuildDataSource.addRange(fieldnum(KCS_GAEBPos, ImportID));
        SalesQuotationTable     salesQuotationTable;
        ;

        salesQuotationTable = common;
        queryBuildRange.value(QueryValue(salesQuotationTable.KCS_GAEBImportID));
        sysTableLookup.addLookupfield(fieldnum(KCS_GAEBPos, OZ));
        sysTableLookup.addLookupfield(fieldnum(KCS_GAEBPos, LfdNr));
        sysTableLookup.addLookupfield(fieldnum(KCS_GAEBPos, PoskennZ));
        sysTableLookup.addLookupfield(fieldnum(KCS_GAEBPos, ShortTxt));
        sysTableLookup.addLookupfield(fieldnum(KCS_GAEBPos, ArtQty));
        sysTableLookup.addLookupfield(fieldnum(KCS_GAEBPos, ME));
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

public void insert()
{
    if (!this.LfdNrInt)
    {
        this.LfdNrInt = str2Int(this.LfdNr);
    }

    super();
}
